import { newSpecPage } from '@stencil/core/testing';
import { ScSubscriptionStatusBadge } from '../sc-subscription-status-badge';

/**
 * A pause is `cancel_at_period_end` + `restore_at`. Without `restore_at` the same
 * shape is a cancellation, so these cases guard against a scheduled pause being
 * labelled "Cancelling".
 */
const render = async (subscription: any) => {
  const page = await newSpecPage({
    components: [ScSubscriptionStatusBadge],
    html: `<sc-subscription-status-badge></sc-subscription-status-badge>`,
  });
  page.root.subscription = subscription;
  await page.waitForChanges();
  return page.root.shadowRoot.textContent.trim();
};

describe('sc-subscription-status-badge', () => {
  it('renders', async () => {
    const page = await newSpecPage({
      components: [ScSubscriptionStatusBadge],
      html: `<sc-subscription-status-badge></sc-subscription-status-badge>`,
    });
    expect(page.root).toMatchSnapshot();
  });

  it('says Pausing when a pause is scheduled', async () => {
    expect(
      await render({
        status: 'active',
        cancel_at_period_end: 1786000000,
        current_period_end_at: 1786000000,
        restore_at: 1817000000,
      }),
    ).toBe('Pausing');
  });

  it('says Cancelling when a cancellation is scheduled', async () => {
    expect(
      await render({
        status: 'active',
        cancel_at_period_end: 1786000000,
        current_period_end_at: 1786000000,
        restore_at: null,
      }),
    ).toBe('Cancelling');
  });

  it('says Paused once the pause has taken effect', async () => {
    expect(await render({ status: 'canceled', restore_at: 1817000000 })).toBe('Paused');
  });

  it('says Canceled when there is no restore date', async () => {
    expect(await render({ status: 'canceled', restore_at: null })).toBe('Canceled');
  });

  it('says Active for a plain active subscription', async () => {
    expect(await render({ status: 'active', current_period_end_at: 1786000000 })).toBe('Active');
  });
});
